	private static ArchiveDirectory listAllFiles(Path currentPath) throws IOException {
		ArchiveDirectory archiveDirectory = new ArchiveDirectory();
		archiveDirectory.setTitle(currentPath.getFileName().toString());
		archiveDirectory.setDirectory(Files.isDirectory(currentPath));
		if (archiveDirectory.isDirectory()) {
			List<ArchiveDirectory> childrens = new ArrayList<>();
			try (DirectoryStream<Path> stream = Files.newDirectoryStream(currentPath)) {
				for (Path entry : stream) {
					childrens.add(listAllFiles(entry));
				}
			}
			archiveDirectory.setChildren(childrens);
		}
		return archiveDirectory;
	}

