package rs.unicredit.cardlifecycle.logging;


import java.net.InetAddress;
import java.net.UnknownHostException;
import java.util.Date;
import java.util.Enumeration;

import org.springframework.beans.factory.annotation.Autowired;
import org.springframework.stereotype.Service;
import org.springframework.util.StringUtils;

import jakarta.servlet.http.HttpServletRequest;

@Service
public class LoggingService {
	
	private final String APPLICATION_NAME = "RSL051";
	private final String LEGAL_ENTITY = "UniCredit Bank Serbia JSC";
	private final String LEVEL_INFO = "INFO";
	private final String LEVEL_ERROR = "ERROR";
	private final String LEVEL_WARNING = "WARNING";
	private final String CLIENT_CODE = "";
	private final String SEC_LOG = "SecLog";
	
	@Autowired
    LoggingRepository loggingRepository;
	
	public void info(HttpServletRequest request, OperationCategory operationCategory, String description)  {
		Log log = setRequestParamsToLog(request);
		log.setOperationDescription(description);
		log.setOperationCategory(operationCategory.toString());
		log.setLogLevel(LEVEL_INFO);
		log.setClientCode(CLIENT_CODE);
		log.setSecLog(SEC_LOG);
		loggingRepository.save(log);
	}
	
	public void error(HttpServletRequest request, OperationCategory operationCategory, String description)  {
		Log log = setRequestParamsToLog(request);
		log.setOperationDescription(description);
		log.setOperationCategory(operationCategory.toString());
		log.setLogLevel(LEVEL_ERROR);
		log.setClientCode(CLIENT_CODE);
		log.setSecLog(SEC_LOG);
		loggingRepository.save(log);	
	}
	
	public void warning(HttpServletRequest request, OperationCategory operationCategory, String description)  {
		Log log = setRequestParamsToLog(request);
		log.setOperationDescription(description);
		log.setOperationCategory(operationCategory.toString());
		log.setLogLevel(LEVEL_WARNING);
		log.setClientCode(CLIENT_CODE);
		log.setSecLog(SEC_LOG);
		loggingRepository.save(log);	
	}
	
	//Paramatre iz request stavlja u Log objekat koji ce biti snimljen.
	private Log setRequestParamsToLog(HttpServletRequest request) {
		Log log = new Log();
		try {
			log.setUserName(request.getUserPrincipal().getName());
		}
		catch(NullPointerException e) {
			log.setUserName("No logged user.");
		}
		log.setUrl(request.getRequestURI().toString());
		log.setRequestType(request.getMethod().toUpperCase());
		log.setPayload(getRequestParameters(request));
		log.setWorkstation(getClientIPAddress(request));
		// Avoid insecure getRequestedSessionId; do not log raw session IDs
		jakarta.servlet.http.HttpSession session = request.getSession(false);
		String sessionIndicator = (session == null) ? "NO_SESSION" : "HAS_SESSION";
		log.setSessionId(sessionIndicator);
		log.setCreatedAt(new Date());
		log.setAppName(APPLICATION_NAME);
		log.setLegalEntity(LEGAL_ENTITY);
		return log;
	}
	
	//Dohvata sve parametre iz zahteva i konketuje u jedan string - PAYLOAD
	private String getRequestParameters(HttpServletRequest httpRequest) {
        String parameters = " ";
	    Enumeration<String> params = httpRequest.getParameterNames();
	    while(params.hasMoreElements()){
	        String paramName = (String)params.nextElement();
	        if (!paramName.equals("password")) {
	        	parameters = parameters +  paramName + "=" + httpRequest.getParameter(paramName)+"; ";
	        	}
	        }
	    return parameters;
	}
	//Trazi IP addressu korisnika iz REQUEST-a
	public String getClientIPAddress(HttpServletRequest request ) {
		String clientIPAddress = request.getHeader("X-Forwarded-For");
		if(!StringUtils.hasLength(clientIPAddress) || "unknown".equals(clientIPAddress)) {
			clientIPAddress = request.getHeader("Proxy-Client-IP");
		}
		if(!StringUtils.hasLength(clientIPAddress) || "unknown".equals(clientIPAddress)) {
			clientIPAddress = request.getHeader("WL-Proxy-Client-IP");
			
		}
		if(!StringUtils.hasLength(clientIPAddress) || "unknown".equals(clientIPAddress)) {
			clientIPAddress = request.getRemoteAddr();
		}
		
		if ("127.0.0.1".equals(clientIPAddress) || "0:0:0:0:0:0:0:1".equals(clientIPAddress)){
			 try {
				 InetAddress inetAddress = InetAddress.getLocalHost();
				 clientIPAddress = inetAddress.getHostAddress();
			} catch (UnknownHostException e) {
				  e.printStackTrace();
			}
			
		}
		
		if (StringUtils.hasLength(clientIPAddress)) {
			int commaIndex = clientIPAddress.indexOf(",");
			if (commaIndex >= 0) {
				clientIPAddress = clientIPAddress.substring(0, commaIndex);
			}
		}
		
		return clientIPAddress;
	}
	

}

