	/**
	 * Utility method to send simple HTML email
	 * @param session
	 * @param toEmail
	 * @param subject
	 * @param body
	 */
	public void sendEmail(Session session, String toEmail, String ccEmail, String bccEmail, String subject, String body) {
		try {
			MimeMessage msg = new MimeMessage(session);
			msg.addHeader("Content-type", "text/HTML; charset=UTF-8");
			msg.addHeader("format", "flowed");
			msg.addHeader("Content-Transfer-Encoding", "8bit");

			msg.setFrom(new InternetAddress(mailFrom, "CardLifeCycle"));
			msg.setReplyTo(InternetAddress.parse(mailReplyTo, false));
			msg.setSubject(subject, "UTF-8");
			msg.setSentDate(new Date());
			msg.setRecipients(Message.RecipientType.TO, InternetAddress.parse(toEmail, false));

			// Provera da li su CC i BCC null pre nego ­to ih dodamo
			if (ccEmail != null && !ccEmail.isEmpty()) {
				msg.setRecipients(Message.RecipientType.CC, InternetAddress.parse(ccEmail, false));
			}

			if (bccEmail != null && !bccEmail.isEmpty()) {
				msg.setRecipients(Message.RecipientType.BCC, InternetAddress.parse(bccEmail, false));
			}

			// Formatiranje tela mejla
			String formattedBody = formatBody(body);
			String htmlBody = "<html>" +
					"<body style='font-family: \"Unicredit\", Courier, monospace; font-size: 16px;'>" +
					formattedBody +
					"</body>" +
					"</html>";
			msg.setContent(htmlBody, "text/html; charset=UTF-8");

			Transport.send(msg);

		} catch (Exception e) {
			e.printStackTrace();
		}
	}


	private String formatBody(String body) {
	    return body
	        .replaceFirst(",", ",<br><br>") // Dodaj dva prazna reda nakon prve zapete
	        .replaceAll("(?<=[.!?,])\\s*", "<br>") // Novi red posle ostalih interpunkcija
	        .replaceFirst("(?s)(.*)(<br>.*<br>.*)$", "$1<br><br>$2"); // Dodaj dva prazna reda pre poslednja dva reda
	}

	public  void sendEmail(String toEmail,String ccEmail, String bccEmail, String subject, String body) throws MalformedURLException {
		logger.info("Send email on address: {}, with CC: {} and subject: {}", toEmail, ccEmail, subject);
		Properties props = System.getProperties();
		props.put("mail.smtp.host", hostServer);
		Session session = Session.getInstance(props, null);
		sendEmail(session, toEmail,ccEmail,bccEmail,subject, body);
	}
