		if (px == null || px.trim().equalsIgnoreCase("")) { // Za prazne PX ne radim update
			logger.info("***********************sendOtpremnice prazan PX za branch :" + branch);
		} else {
			otvoreneOtpremnice.forEach((o) -> {
