				o.setEan(px); // postavljanje ean-a na osnovu Stevinog trigera TRIGGER
								// UCBCARDN.perso_otpremnice_after_update
				o.setOStatus(status_Otp_closed); // postavljanje statusa otpremnice na closed
				// o.setOPxcode(px); // vec uneto kroz fillPxCodeOtpremnice
				o.setODatum(currentDateAndTime);
				o.setStampaXlsx(0); // vracanja na ponovnu stampu xlsx-a za postu
			});
