			if (!file.exists() && !file.createNewFile()) {
				throw new IOException("Could not create export file: " + filePath);
			}
			FileOutputStream fileOutStream = null;
			/* Formiranje fajla (generisanjeHSMFajla) za export */
			String normalPan = perso.getCardNumber();
			String val = "4";
			String spacePan = normalPan.replaceAll("(.{" + val + "})", "$1 ").trim();

			String red = rightpad(nvl(perso.getSearchCode(), ""), 6) + "$" + rightpad(spacePan, 19) + "@"
