					rightpad(nvl(perso.getMagneticStripTrackOne(), ""), 78)
					+ rightpad(nvl(perso.getMagneticStripTrackTwo(), ""), 39) + "#"
					+ rightpad(nvl(perso.getEan(), ""), 13) + "@" + rightpad("", 15) + "@" + // TITLE/SALUTATION
