					"#END#";

//			logger.info("***Absolute path card: {}", p.toAbsolutePath());

			try (OutputStream out = new BufferedOutputStream(Files.newOutputStream(p, StandardOpenOption.APPEND))) {
				out.write(red.getBytes());
				out.write("\r\n".getBytes());

				out.flush();
				out.close();

				/* Arhivu export fajlova */
				String toArchive = fileService.createExportedArchiveStructureIfNotExist();
